def colour_existing_trades(apps, schema_editor):
    Trade = apps.get_model("catalog", "Trade")
    for trade in Trade.objects.all():
        words = " ".join([trade.name, trade.slug, *(trade.synonyms or [])]).lower()
        for colour, stems in STARTING_COLOURS:
            if any(stem in words for stem in stems):
                trade.colour = colour
                trade.save(update_fields=["colour"])
                break


